WITH flattened AS (SELECT id, service, host, log_ts, level, status_code, attr_key, value FROM app_logs LATERAL VIEW EXPLODE(context) t AS attr_key, value) SELECT DATE_TRUNC('HOUR', log_ts) AS hour_window, AVG(status_code) FILTER (WHERE level = 'INFO') AS info_avg_status_code, MIN(log_ts) AS started_at, ROUND(SUM(status_code) / NULLIF(COUNT(CASE WHEN service = 'checkout' THEN 1 END), 0), 2) AS status_code_per_checkout FROM flattened GROUP BY hour_window;
